        and (not (v_filters -> 'ownerType' is not null and jsonb_typeof(v_filters -> 'ownerType') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerType') = 'array' and jsonb_array_length(v_filters -> 'ownerType') = 0)) or (k."owner_type")::text = any((case when jsonb_typeof(v_filters -> 'ownerType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerType')) else array[v_filters ->> 'ownerType'] end)::text[]))
