        and (not (v_filters -> 'counterpartyId' is not null and jsonb_typeof(v_filters -> 'counterpartyId') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyId') = 'array' and jsonb_array_length(v_filters -> 'counterpartyId') = 0)) or (x."counterparty_id")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyId')) else array[v_filters ->> 'counterpartyId'] end)::text[]))
        and (not (v_filters -> 'renewingBefore' is not null and jsonb_typeof(v_filters -> 'renewingBefore') <> 'null' and not (jsonb_typeof(v_filters -> 'renewingBefore') = 'array' and jsonb_array_length(v_filters -> 'renewingBefore') = 0)) or (x."status" = 'active' and case when x."ends_on" is null then null else x."ends_on" - x."notice_days" end <= (v_filters ->> 'renewingBefore')::date))
        and (v_search is null or x."title" ilike v_search or x."description" ilike v_search)
        and (v_after is null or (coalesce(x."starts_on", date '0001-01-01') <= (v_after ->> 0)::date and ((coalesce(x."starts_on", date '0001-01-01') < (v_after ->> 0)::date) or (coalesce(x."starts_on", date '0001-01-01') = (v_after ->> 0)::date and x."id" > (v_after ->> 1)::uuid))))
      order by coalesce(x."starts_on", date '0001-01-01') desc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort = 'title' and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'CONTRACT_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'title', x."title", 'description', x."description", 'counterpartyType', x."counterparty_type", 'counterpartyId', x."counterparty_id", 'ownerId', x."owner_id", 'status', x."status", 'value', x."value"::text, 'currency', x."currency", 'startsOn', x."starts_on", 'endsOn', x."ends_on", 'autoRenew', x."auto_renew", 'renewalMonths', x."renewal_months", 'noticeDays', x."notice_days", 'noticeDeadline', case when x."ends_on" is null then null else x."ends_on" - x."notice_days" end, 'renewedCount', x."renewed_count", 'signatureRequestId', x."signature_request_id", 'signedAt', x."signed_at", 'terminatedAt', x."terminated_at", 'terminationReason', x."termination_reason", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") as j, jsonb_build_array((lower(x."title"))::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."contracts" x
      where x."tenant_id" = page_contracts.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'counterpartyType' is not null and jsonb_typeof(v_filters -> 'counterpartyType') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyType') = 'array' and jsonb_array_length(v_filters -> 'counterpartyType') = 0)) or (x."counterparty_type")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyType')) else array[v_filters ->> 'counterpartyType'] end)::text[]))
        and (not (v_filters -> 'counterpartyId' is not null and jsonb_typeof(v_filters -> 'counterpartyId') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyId') = 'array' and jsonb_array_length(v_filters -> 'counterpartyId') = 0)) or (x."counterparty_id")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyId')) else array[v_filters ->> 'counterpartyId'] end)::text[]))
        and (not (v_filters -> 'renewingBefore' is not null and jsonb_typeof(v_filters -> 'renewingBefore') <> 'null' and not (jsonb_typeof(v_filters -> 'renewingBefore') = 'array' and jsonb_array_length(v_filters -> 'renewingBefore') = 0)) or (x."status" = 'active' and case when x."ends_on" is null then null else x."ends_on" - x."notice_days" end <= (v_filters ->> 'renewingBefore')::date))
        and (v_search is null or x."title" ilike v_search or x."description" ilike v_search)
        and (v_after is null or (lower(x."title"), x."id") > ((v_after ->> 0)::text, (v_after ->> 1)::uuid))
      order by lower(x."title") asc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort = 'title' and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'CONTRACT_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'title', x."title", 'description', x."description", 'counterpartyType', x."counterparty_type", 'counterpartyId', x."counterparty_id", 'ownerId', x."owner_id", 'status', x."status", 'value', x."value"::text, 'currency', x."currency", 'startsOn', x."starts_on", 'endsOn', x."ends_on", 'autoRenew', x."auto_renew", 'renewalMonths', x."renewal_months", 'noticeDays', x."notice_days", 'noticeDeadline', case when x."ends_on" is null then null else x."ends_on" - x."notice_days" end, 'renewedCount', x."renewed_count", 'signatureRequestId', x."signature_request_id", 'signedAt', x."signed_at", 'terminatedAt', x."terminated_at", 'terminationReason', x."termination_reason", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") as j, jsonb_build_array((lower(x."title"))::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."contracts" x
      where x."tenant_id" = page_contracts.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'counterpartyType' is not null and jsonb_typeof(v_filters -> 'counterpartyType') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyType') = 'array' and jsonb_array_length(v_filters -> 'counterpartyType') = 0)) or (x."counterparty_type")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyType')) else array[v_filters ->> 'counterpartyType'] end)::text[]))
        and (not (v_filters -> 'counterpartyId' is not null and jsonb_typeof(v_filters -> 'counterpartyId') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyId') = 'array' and jsonb_array_length(v_filters -> 'counterpartyId') = 0)) or (x."counterparty_id")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyId')) else array[v_filters ->> 'counterpartyId'] end)::text[]))
        and (not (v_filters -> 'renewingBefore' is not null and jsonb_typeof(v_filters -> 'renewingBefore') <> 'null' and not (jsonb_typeof(v_filters -> 'renewingBefore') = 'array' and jsonb_array_length(v_filters -> 'renewingBefore') = 0)) or (x."status" = 'active' and case when x."ends_on" is null then null else x."ends_on" - x."notice_days" end <= (v_filters ->> 'renewingBefore')::date))
        and (v_search is null or x."title" ilike v_search or x."description" ilike v_search)
        and (v_after is null or (lower(x."title") <= (v_after ->> 0)::text and ((lower(x."title") < (v_after ->> 0)::text) or (lower(x."title") = (v_after ->> 0)::text and x."id" > (v_after ->> 1)::uuid))))
      order by lower(x."title") desc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  end if;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."contracts" x
      where x."tenant_id" = page_contracts.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'counterpartyType' is not null and jsonb_typeof(v_filters -> 'counterpartyType') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyType') = 'array' and jsonb_array_length(v_filters -> 'counterpartyType') = 0)) or (x."counterparty_type")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyType')) else array[v_filters ->> 'counterpartyType'] end)::text[]))
        and (not (v_filters -> 'counterpartyId' is not null and jsonb_typeof(v_filters -> 'counterpartyId') <> 'null' and not (jsonb_typeof(v_filters -> 'counterpartyId') = 'array' and jsonb_array_length(v_filters -> 'counterpartyId') = 0)) or (x."counterparty_id")::text = any((case when jsonb_typeof(v_filters -> 'counterpartyId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'counterpartyId')) else array[v_filters ->> 'counterpartyId'] end)::text[]))
        and (not (v_filters -> 'renewingBefore' is not null and jsonb_typeof(v_filters -> 'renewingBefore') <> 'null' and not (jsonb_typeof(v_filters -> 'renewingBefore') = 'array' and jsonb_array_length(v_filters -> 'renewingBefore') = 0)) or (x."status" = 'active' and case when x."ends_on" is null then null else x."ends_on" - x."notice_days" end <= (v_filters ->> 'renewingBefore')::date))
        and (v_search is null or x."title" ilike v_search or x."description" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.page_conversations (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(page_conversations.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_sort text := nullif(v_filters ->> 'sort', '');
  v_dir text := nullif(v_filters ->> 'direction', '');
  v_facet text := nullif(v_filters ->> 'facet', '');
  v_count boolean := coalesce((v_filters ->> 'count')::boolean, false);
  v_result jsonb;
begin
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'MESSAGING_INVALID';
  end if;
  if v_facet is not null then
    if v_facet not in ('kind') then
      raise exception 'facet is one of kind' using errcode = '22023', hint = 'MESSAGING_INVALID';
    end if;
    with s as (
      select (case v_facet when 'kind' then (x."kind")::text end) as v
      from "better_supabase"."conversations" x
      where x."tenant_id" = page_conversations.tenant
        and exists (select 1 from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid())
        and (case when not (v_filters -> 'kind' is not null and jsonb_typeof(v_filters -> 'kind') <> 'null' and not (jsonb_typeof(v_filters -> 'kind') = 'array' and jsonb_array_length(v_filters -> 'kind') = 0)) then x."kind" <> 'inbox' else (not (v_filters -> 'kind' is not null and jsonb_typeof(v_filters -> 'kind') <> 'null' and not (jsonb_typeof(v_filters -> 'kind') = 'array' and jsonb_array_length(v_filters -> 'kind') = 0)) or (x."kind")::text = any((case when jsonb_typeof(v_filters -> 'kind') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'kind')) else array[v_filters ->> 'kind'] end)::text[])) end)
        and (v_search is null or x."title" ilike v_search)
      limit v_total_cap + 1
    )
    select jsonb_build_object('facet', v_facet, 'values', coalesce(jsonb_agg(jsonb_build_object('value', g.v, 'count', jsonb_build_object('value', g.n, 'exact', g.exact)) order by g.n desc, g.v), '[]'::jsonb))
    into v_result
    from (
      select s.v, count(*) as n, (select count(*) from s) <= v_total_cap as exact
      from s where s.v is not null group by s.v order by n desc, s.v limit 100
    ) g;
    return v_result;
  end if;
  if v_count then
    select count(*) into v_total from (
      select 1 from "better_supabase"."conversations" x
      where x."tenant_id" = page_conversations.tenant
        and exists (select 1 from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid())
        and (case when not (v_filters -> 'kind' is not null and jsonb_typeof(v_filters -> 'kind') <> 'null' and not (jsonb_typeof(v_filters -> 'kind') = 'array' and jsonb_array_length(v_filters -> 'kind') = 0)) then x."kind" <> 'inbox' else (not (v_filters -> 'kind' is not null and jsonb_typeof(v_filters -> 'kind') <> 'null' and not (jsonb_typeof(v_filters -> 'kind') = 'array' and jsonb_array_length(v_filters -> 'kind') = 0)) or (x."kind")::text = any((case when jsonb_typeof(v_filters -> 'kind') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'kind')) else array[v_filters ->> 'kind'] end)::text[])) end)
        and (v_search is null or x."title" ilike v_search)
      limit v_total_cap + 1
    ) c;
    return jsonb_build_object('value', least(v_total, v_total_cap), 'exact', v_total <= v_total_cap);
  end if;
  if v_sort is not null and v_sort not in ('lastMessageAt', 'createdAt', 'title') then
    raise exception 'sort is one of lastMessageAt, createdAt, title' using errcode = '22023', hint = 'MESSAGING_INVALID';
  end if;
  if v_dir is not null and v_dir not in ('asc', 'desc') then
    raise exception 'direction is asc or desc' using errcode = '22023', hint = 'MESSAGING_INVALID';
  end if;
  if v_sort is null and coalesce(v_dir, 'desc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'MESSAGING_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, to_jsonb(x) || jsonb_build_object(
      'unread', (select count(*) from "better_supabase"."messages" m, "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid() and m."conversation_id" = x."id" and (m."thread_id" is null or m."broadcast") and m."sent_at" > coalesce(k."last_read_at", '-infinity'::timestamptz) and m."archived_at" is null and m."author_id" is distinct from auth.uid()),
      'mentions', (select count(*) filter (where auth.uid() = any (m."mentions") or m."mention_scope" is not null) from "better_supabase"."messages" m, "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid() and m."conversation_id" = x."id" and (m."thread_id" is null or m."broadcast") and m."sent_at" > coalesce(k."last_read_at", '-infinity'::timestamptz) and m."archived_at" is null and m."author_id" is distinct from auth.uid()),
      'lastReadAt', (select k."last_read_at" from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid()),
      'notify', (select k."notify" from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid())
    ) as j, jsonb_build_array((coalesce(x."last_message_at", 'epoch'::timestamptz))::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."conversations" x
      where x."tenant_id" = page_conversations.tenant
        and exists (select 1 from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid())
        and (case when not (v_filters -> 'kind' is not null and jsonb_typeof(v_filters -> 'kind') <> 'null' and not (jsonb_typeof(v_filters -> 'kind') = 'array' and jsonb_array_length(v_filters -> 'kind') = 0)) then x."kind" <> 'inbox' else (not (v_filters -> 'kind' is not null and jsonb_typeof(v_filters -> 'kind') <> 'null' and not (jsonb_typeof(v_filters -> 'kind') = 'array' and jsonb_array_length(v_filters -> 'kind') = 0)) or (x."kind")::text = any((case when jsonb_typeof(v_filters -> 'kind') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'kind')) else array[v_filters ->> 'kind'] end)::text[])) end)
        and (v_search is null or x."title" ilike v_search)
        and (v_after is null or (coalesce(x."last_message_at", 'epoch'::timestamptz), x."id") > ((v_after ->> 0)::timestamptz, (v_after ->> 1)::uuid))
      order by coalesce(x."last_message_at", 'epoch'::timestamptz) asc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort is null and coalesce(v_dir, 'desc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'MESSAGING_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, to_jsonb(x) || jsonb_build_object(
      'unread', (select count(*) from "better_supabase"."messages" m, "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid() and m."conversation_id" = x."id" and (m."thread_id" is null or m."broadcast") and m."sent_at" > coalesce(k."last_read_at", '-infinity'::timestamptz) and m."archived_at" is null and m."author_id" is distinct from auth.uid()),
      'mentions', (select count(*) filter (where auth.uid() = any (m."mentions") or m."mention_scope" is not null) from "better_supabase"."messages" m, "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid() and m."conversation_id" = x."id" and (m."thread_id" is null or m."broadcast") and m."sent_at" > coalesce(k."last_read_at", '-infinity'::timestamptz) and m."archived_at" is null and m."author_id" is distinct from auth.uid()),
      'lastReadAt', (select k."last_read_at" from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid()),
      'notify', (select k."notify" from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid())
    ) as j, jsonb_build_array((coalesce(x."last_message_at", 'epoch'::timestamptz))::text, (x."id")::text) as k
    from (
