        and (not (v_filters -> 'pipelineId' is not null and jsonb_typeof(v_filters -> 'pipelineId') <> 'null' and not (jsonb_typeof(v_filters -> 'pipelineId') = 'array' and jsonb_array_length(v_filters -> 'pipelineId') = 0)) or x."pipeline_id"::text = any((case when jsonb_typeof(v_filters -> 'pipelineId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'pipelineId')) else array[v_filters ->> 'pipelineId'] end)::text[]))
        and (not (v_filters -> 'stageId' is not null and jsonb_typeof(v_filters -> 'stageId') <> 'null' and not (jsonb_typeof(v_filters -> 'stageId') = 'array' and jsonb_array_length(v_filters -> 'stageId') = 0)) or x."stage_id"::text = any((case when jsonb_typeof(v_filters -> 'stageId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'stageId')) else array[v_filters ->> 'stageId'] end)::text[]))
        and (not (v_filters -> 'outcome' is not null and jsonb_typeof(v_filters -> 'outcome') <> 'null' and not (jsonb_typeof(v_filters -> 'outcome') = 'array' and jsonb_array_length(v_filters -> 'outcome') = 0)) or x."outcome"::text = any((case when jsonb_typeof(v_filters -> 'outcome') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'outcome')) else array[v_filters ->> 'outcome'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'motion' is not null and jsonb_typeof(v_filters -> 'motion') <> 'null' and not (jsonb_typeof(v_filters -> 'motion') = 'array' and jsonb_array_length(v_filters -> 'motion') = 0)) or x."motion"::text = any((case when jsonb_typeof(v_filters -> 'motion') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'motion')) else array[v_filters ->> 'motion'] end)::text[]))
        and (not (v_filters -> 'priority' is not null and jsonb_typeof(v_filters -> 'priority') <> 'null' and not (jsonb_typeof(v_filters -> 'priority') = 'array' and jsonb_array_length(v_filters -> 'priority') = 0)) or x."priority"::text = any((case when jsonb_typeof(v_filters -> 'priority') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'priority')) else array[v_filters ->> 'priority'] end)::text[]))
        and (not (v_filters -> 'forecast' is not null and jsonb_typeof(v_filters -> 'forecast') <> 'null' and not (jsonb_typeof(v_filters -> 'forecast') = 'array' and jsonb_array_length(v_filters -> 'forecast') = 0)) or x."forecast_category"::text = any((case when jsonb_typeof(v_filters -> 'forecast') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'forecast')) else array[v_filters ->> 'forecast'] end)::text[]))
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (not (v_filters -> 'companyId' is not null and jsonb_typeof(v_filters -> 'companyId') <> 'null' and not (jsonb_typeof(v_filters -> 'companyId') = 'array' and jsonb_array_length(v_filters -> 'companyId') = 0)) or x."company_id"::text = any((case when jsonb_typeof(v_filters -> 'companyId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'companyId')) else array[v_filters ->> 'companyId'] end)::text[]))
        and (v_search is null or x."name" ilike v_search or x."identifier" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.page_document_templates (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(page_document_templates.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_sort text := nullif(v_filters ->> 'sort', '');
  v_dir text := nullif(v_filters ->> 'direction', '');
  v_facet text := nullif(v_filters ->> 'facet', '');
  v_count boolean := coalesce((v_filters ->> 'count')::boolean, false);
  v_result jsonb;
begin
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  if v_facet is not null then
    if v_facet not in ('documentType', 'active', 'language') then
      raise exception 'facet is one of documentType, active, language' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
    end if;
    with s as (
      select (case v_facet when 'documentType' then (t."document_type")::text when 'active' then (t."active"::text)::text when 'language' then (t."language")::text end) as v
      from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
      limit v_total_cap + 1
    )
    select jsonb_build_object('facet', v_facet, 'values', coalesce(jsonb_agg(jsonb_build_object('value', g.v, 'count', jsonb_build_object('value', g.n, 'exact', g.exact)) order by g.n desc, g.v), '[]'::jsonb))
    into v_result
    from (
      select s.v, count(*) as n, (select count(*) from s) <= v_total_cap as exact
      from s where s.v is not null group by s.v order by n desc, s.v limit 100
    ) g;
    return v_result;
  end if;
  if v_count then
    select count(*) into v_total from (
      select 1 from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
      limit v_total_cap + 1
    ) c;
    return jsonb_build_object('value', least(v_total, v_total_cap), 'exact', v_total <= v_total_cap);
  end if;
  if v_sort is not null and v_sort not in ('name', 'updatedAt') then
    raise exception 'sort is one of name, updatedAt' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  if v_dir is not null and v_dir not in ('asc', 'desc') then
    raise exception 'direction is asc or desc' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  if v_sort is null and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', t."id", 'organizationId', t."tenant_id", 'legalEntityId', t."legal_entity_id", 'documentType', t."document_type", 'language', t."language", 'name', t."name", 'body', t."body", 'version', t."version", 'active', t."active", 'createdAt', t."created_at", 'updatedAt', t."updated_at") as j, jsonb_build_array((t."name")::text, (t."id")::text) as k
    from (
      select * from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
        and (v_after is null or (t."name", t."id") > ((v_after ->> 0)::text, (v_after ->> 1)::uuid))
      order by t."name" asc, t."id" asc
      limit v_limit + 1 offset v_offset
    ) t
  ) p;
  elsif v_sort is null and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', t."id", 'organizationId', t."tenant_id", 'legalEntityId', t."legal_entity_id", 'documentType', t."document_type", 'language', t."language", 'name', t."name", 'body', t."body", 'version', t."version", 'active', t."active", 'createdAt', t."created_at", 'updatedAt', t."updated_at") as j, jsonb_build_array((t."name")::text, (t."id")::text) as k
    from (
      select * from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
        and (v_after is null or (t."name" <= (v_after ->> 0)::text and ((t."name" < (v_after ->> 0)::text) or (t."name" = (v_after ->> 0)::text and t."id" > (v_after ->> 1)::uuid))))
      order by t."name" desc, t."id" asc
      limit v_limit + 1 offset v_offset
    ) t
  ) p;
  elsif v_sort = 'name' and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', t."id", 'organizationId', t."tenant_id", 'legalEntityId', t."legal_entity_id", 'documentType', t."document_type", 'language', t."language", 'name', t."name", 'body', t."body", 'version', t."version", 'active', t."active", 'createdAt', t."created_at", 'updatedAt', t."updated_at") as j, jsonb_build_array((t."name")::text, (t."id")::text) as k
    from (
      select * from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
        and (v_after is null or (t."name", t."id") > ((v_after ->> 0)::text, (v_after ->> 1)::uuid))
      order by t."name" asc, t."id" asc
      limit v_limit + 1 offset v_offset
    ) t
  ) p;
  elsif v_sort = 'name' and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', t."id", 'organizationId', t."tenant_id", 'legalEntityId', t."legal_entity_id", 'documentType', t."document_type", 'language', t."language", 'name', t."name", 'body', t."body", 'version', t."version", 'active', t."active", 'createdAt', t."created_at", 'updatedAt', t."updated_at") as j, jsonb_build_array((t."name")::text, (t."id")::text) as k
    from (
      select * from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
        and (v_after is null or (t."name" <= (v_after ->> 0)::text and ((t."name" < (v_after ->> 0)::text) or (t."name" = (v_after ->> 0)::text and t."id" > (v_after ->> 1)::uuid))))
      order by t."name" desc, t."id" asc
      limit v_limit + 1 offset v_offset
    ) t
  ) p;
  elsif v_sort = 'updatedAt' and coalesce(v_dir, 'desc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', t."id", 'organizationId', t."tenant_id", 'legalEntityId', t."legal_entity_id", 'documentType', t."document_type", 'language', t."language", 'name', t."name", 'body', t."body", 'version', t."version", 'active', t."active", 'createdAt', t."created_at", 'updatedAt', t."updated_at") as j, jsonb_build_array((t."updated_at")::text, (t."id")::text) as k
    from (
      select * from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
        and (v_after is null or (t."updated_at", t."id") > ((v_after ->> 0)::timestamptz, (v_after ->> 1)::uuid))
      order by t."updated_at" asc, t."id" asc
      limit v_limit + 1 offset v_offset
    ) t
  ) p;
  elsif v_sort = 'updatedAt' and coalesce(v_dir, 'desc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', t."id", 'organizationId', t."tenant_id", 'legalEntityId', t."legal_entity_id", 'documentType', t."document_type", 'language', t."language", 'name', t."name", 'body', t."body", 'version', t."version", 'active', t."active", 'createdAt', t."created_at", 'updatedAt', t."updated_at") as j, jsonb_build_array((t."updated_at")::text, (t."id")::text) as k
    from (
      select * from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
        and (v_after is null or (t."updated_at" <= (v_after ->> 0)::timestamptz and ((t."updated_at" < (v_after ->> 0)::timestamptz) or (t."updated_at" = (v_after ->> 0)::timestamptz and t."id" > (v_after ->> 1)::uuid))))
      order by t."updated_at" desc, t."id" asc
      limit v_limit + 1 offset v_offset
    ) t
  ) p;
  end if;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."document_templates" t
      where t."tenant_id" = page_document_templates.tenant
        and (not (v_filters -> 'documentType' is not null and jsonb_typeof(v_filters -> 'documentType') <> 'null' and not (jsonb_typeof(v_filters -> 'documentType') = 'array' and jsonb_array_length(v_filters -> 'documentType') = 0)) or (t."document_type")::text = any((case when jsonb_typeof(v_filters -> 'documentType') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'documentType')) else array[v_filters ->> 'documentType'] end)::text[]))
        and (not (v_filters -> 'legalEntityId' is not null and jsonb_typeof(v_filters -> 'legalEntityId') <> 'null' and not (jsonb_typeof(v_filters -> 'legalEntityId') = 'array' and jsonb_array_length(v_filters -> 'legalEntityId') = 0)) or t."legal_entity_id" = any((case when jsonb_typeof(v_filters -> 'legalEntityId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'legalEntityId')) else array[v_filters ->> 'legalEntityId'] end)::uuid[]))
        and (not (v_filters -> 'language' is not null and jsonb_typeof(v_filters -> 'language') <> 'null' and not (jsonb_typeof(v_filters -> 'language') = 'array' and jsonb_array_length(v_filters -> 'language') = 0)) or (coalesce(t."language", ''))::text = any((case when jsonb_typeof(v_filters -> 'language') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'language')) else array[v_filters ->> 'language'] end)::text[]))
        and (not (v_filters -> 'active' is not null and jsonb_typeof(v_filters -> 'active') <> 'null' and not (jsonb_typeof(v_filters -> 'active') = 'array' and jsonb_array_length(v_filters -> 'active') = 0)) or t."active"::text = any((case when jsonb_typeof(v_filters -> 'active') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'active')) else array[v_filters ->> 'active'] end)::text[]))
        and (v_search is null or t."name" ilike v_search or t."document_type" ilike v_search or t."body" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.page_drive_documents (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(page_drive_documents.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_sort text := nullif(v_filters ->> 'sort', '');
  v_dir text := nullif(v_filters ->> 'direction', '');
  v_facet text := nullif(v_filters ->> 'facet', '');
  v_count boolean := coalesce((v_filters ->> 'count')::boolean, false);
  v_result jsonb;
begin
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'DRIVE_DOCUMENT_FILTER_INVALID';
  end if;
  if v_facet is not null then
    if v_facet not in ('type', 'status', 'review') then
      raise exception 'facet is one of type, status, review' using errcode = '22023', hint = 'DRIVE_DOCUMENT_FILTER_INVALID';
    end if;
    with s as (
      select (case v_facet when 'type' then (x."document_type")::text when 'status' then (x."document_status")::text when 'review' then (case when x."document_status" = 'effective' and x."next_review_on" <= current_date then 'due' else 'ok' end)::text end) as v
      from "better_supabase"."drive_nodes" x
      where x."tenant_id" = page_drive_documents.tenant
        and x."document_status" is not null
        and x."archived_at" is null
        and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or "better_supabase"."drive_can"(x."id", 'viewer'))
        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or (x."document_type")::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."document_status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."document_owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'review' is not null and jsonb_typeof(v_filters -> 'review') <> 'null' and not (jsonb_typeof(v_filters -> 'review') = 'array' and jsonb_array_length(v_filters -> 'review') = 0)) or (case when x."document_status" = 'effective' and x."next_review_on" <= current_date then 'due' else 'ok' end)::text = any((case when jsonb_typeof(v_filters -> 'review') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'review')) else array[v_filters ->> 'review'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{reviewDue,0}', v_filters ->> 'reviewDue'), '') = 'true', false) or (x."document_status" = 'effective' and x."next_review_on" <= current_date))
        and (v_search is null or x."document_number" ilike v_search or x."name" ilike v_search)
      limit v_total_cap + 1
    )
    select jsonb_build_object('facet', v_facet, 'values', coalesce(jsonb_agg(jsonb_build_object('value', g.v, 'count', jsonb_build_object('value', g.n, 'exact', g.exact)) order by g.n desc, g.v), '[]'::jsonb))
    into v_result
    from (
      select s.v, count(*) as n, (select count(*) from s) <= v_total_cap as exact
      from s where s.v is not null group by s.v order by n desc, s.v limit 100
    ) g;
    return v_result;
  end if;
  if v_count then
    select count(*) into v_total from (
      select 1 from "better_supabase"."drive_nodes" x
      where x."tenant_id" = page_drive_documents.tenant
        and x."document_status" is not null
        and x."archived_at" is null
        and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or "better_supabase"."drive_can"(x."id", 'viewer'))
        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or (x."document_type")::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."document_status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."document_owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'review' is not null and jsonb_typeof(v_filters -> 'review') <> 'null' and not (jsonb_typeof(v_filters -> 'review') = 'array' and jsonb_array_length(v_filters -> 'review') = 0)) or (case when x."document_status" = 'effective' and x."next_review_on" <= current_date then 'due' else 'ok' end)::text = any((case when jsonb_typeof(v_filters -> 'review') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'review')) else array[v_filters ->> 'review'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{reviewDue,0}', v_filters ->> 'reviewDue'), '') = 'true', false) or (x."document_status" = 'effective' and x."next_review_on" <= current_date))
        and (v_search is null or x."document_number" ilike v_search or x."name" ilike v_search)
      limit v_total_cap + 1
    ) c;
    return jsonb_build_object('value', least(v_total, v_total_cap), 'exact', v_total <= v_total_cap);
  end if;
  if v_sort is not null and v_sort not in ('number', 'name', 'nextReviewOn') then
    raise exception 'sort is one of number, name, nextReviewOn' using errcode = '22023', hint = 'DRIVE_DOCUMENT_FILTER_INVALID';
  end if;
  if v_dir is not null and v_dir not in ('asc', 'desc') then
    raise exception 'direction is asc or desc' using errcode = '22023', hint = 'DRIVE_DOCUMENT_FILTER_INVALID';
  end if;
  if v_sort is null and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DRIVE_DOCUMENT_FILTER_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, ("better_supabase"."drive_node_json"(x) || jsonb_build_object('role', "better_supabase"."drive_role"((x)."id"), 'readOnly', (coalesce((x)."source"::text, 'internal') not in ('internal', 'request') or false), 'held', "better_supabase"."drive_node_held"((x)."id"), 'downloadable', "better_supabase"."drive_can_download"((x)."id"))) as j, jsonb_build_array((x."document_number")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."drive_nodes" x
      where x."tenant_id" = page_drive_documents.tenant
        and x."document_status" is not null
        and x."archived_at" is null
        and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or "better_supabase"."drive_can"(x."id", 'viewer'))
        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or (x."document_type")::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."document_status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."document_owner_id"::text = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::text[]))
        and (not (v_filters -> 'review' is not null and jsonb_typeof(v_filters -> 'review') <> 'null' and not (jsonb_typeof(v_filters -> 'review') = 'array' and jsonb_array_length(v_filters -> 'review') = 0)) or (case when x."document_status" = 'effective' and x."next_review_on" <= current_date then 'due' else 'ok' end)::text = any((case when jsonb_typeof(v_filters -> 'review') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'review')) else array[v_filters ->> 'review'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{reviewDue,0}', v_filters ->> 'reviewDue'), '') = 'true', false) or (x."document_status" = 'effective' and x."next_review_on" <= current_date))
        and (v_search is null or x."document_number" ilike v_search or x."name" ilike v_search)
        and (v_after is null or (x."document_number", x."id") > ((v_after ->> 0)::text, (v_after ->> 1)::uuid))
      order by x."document_number" asc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort is null and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'DRIVE_DOCUMENT_FILTER_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, ("better_supabase"."drive_node_json"(x) || jsonb_build_object('role', "better_supabase"."drive_role"((x)."id"), 'readOnly', (coalesce((x)."source"::text, 'internal') not in ('internal', 'request') or false), 'held', "better_supabase"."drive_node_held"((x)."id"), 'downloadable', "better_supabase"."drive_can_download"((x)."id"))) as j, jsonb_build_array((x."document_number")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."drive_nodes" x
      where x."tenant_id" = page_drive_documents.tenant
        and x."document_status" is not null
