        and (not (v_filters -> 'model' is not null and jsonb_typeof(v_filters -> 'model') <> 'null' and not (jsonb_typeof(v_filters -> 'model') = 'array' and jsonb_array_length(v_filters -> 'model') = 0)) or (x."model")::text = any((case when jsonb_typeof(v_filters -> 'model') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'model')) else array[v_filters ->> 'model'] end)::text[]))
        and (not (v_filters -> 'promptName' is not null and jsonb_typeof(v_filters -> 'promptName') <> 'null' and not (jsonb_typeof(v_filters -> 'promptName') = 'array' and jsonb_array_length(v_filters -> 'promptName') = 0)) or (x."prompt_name")::text = any((case when jsonb_typeof(v_filters -> 'promptName') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'promptName')) else array[v_filters ->> 'promptName'] end)::text[]))
        and (v_search is null or x."prompt_name" ilike v_search or x."model" ilike v_search)
      limit v_total_cap + 1
