        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or d."type"::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{sensitive,0}', v_filters ->> 'sensitive'), '') = 'true', false) or d."sensitive")
        and (coalesce(nullif(coalesce(v_filters #>> '{archived,0}', v_filters ->> 'archived'), '') = 'true', false) or d."archived_at" is null)
        and (v_search is null or d."key" ilike v_search or d."label" ilike v_search)
        and (v_after is null or (d."type"::text <= (v_after ->> 0)::text and ((d."type"::text < (v_after ->> 0)::text) or (d."type"::text = (v_after ->> 0)::text and d."id" > (v_after ->> 1)::uuid))))
      order by d."type"::text desc, d."id" asc
      limit v_limit + 1 offset v_offset
    ) d
  ) p;
  elsif v_sort = 'rank' and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 4) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'CUSTOM_FIELD_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object(
    'id', d."id",
    'entity', d."entity",
    'key', d."key",
    'label', d."label",
    'type', d."type",
    'required', d."required",
    'sensitive', d."sensitive",
    'encrypted', d."encrypted",
    'pack', d."pack",
    'packVersion', d."pack_version",
    'archivedAt', d."archived_at",
    'rank', d."rank"
  ) as j, jsonb_build_array((d."entity")::text, (d."rank" collate "C")::text, (d."key")::text, (d."id")::text) as k
    from (
      select * from "better_supabase"."field_definitions" d
      where d."tenant_id" = page_field_definitions.tenant
        and (not (v_filters -> 'entity' is not null and jsonb_typeof(v_filters -> 'entity') <> 'null' and not (jsonb_typeof(v_filters -> 'entity') = 'array' and jsonb_array_length(v_filters -> 'entity') = 0)) or (d."entity")::text = any((case when jsonb_typeof(v_filters -> 'entity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'entity')) else array[v_filters ->> 'entity'] end)::text[]))
        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or d."type"::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{sensitive,0}', v_filters ->> 'sensitive'), '') = 'true', false) or d."sensitive")
        and (coalesce(nullif(coalesce(v_filters #>> '{archived,0}', v_filters ->> 'archived'), '') = 'true', false) or d."archived_at" is null)
        and (v_search is null or d."key" ilike v_search or d."label" ilike v_search)
        and (v_after is null or (d."entity", d."rank" collate "C", d."key", d."id") > ((v_after ->> 0)::text, (v_after ->> 1)::text, (v_after ->> 2)::text, (v_after ->> 3)::uuid))
      order by d."entity" asc, d."rank" collate "C" asc, d."key" asc, d."id" asc
      limit v_limit + 1 offset v_offset
    ) d
  ) p;
  elsif v_sort = 'rank' and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 4) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'CUSTOM_FIELD_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object(
    'id', d."id",
    'entity', d."entity",
    'key', d."key",
    'label', d."label",
    'type', d."type",
    'required', d."required",
    'sensitive', d."sensitive",
    'encrypted', d."encrypted",
    'pack', d."pack",
    'packVersion', d."pack_version",
    'archivedAt', d."archived_at",
    'rank', d."rank"
  ) as j, jsonb_build_array((d."entity")::text, (d."rank" collate "C")::text, (d."key")::text, (d."id")::text) as k
    from (
      select * from "better_supabase"."field_definitions" d
      where d."tenant_id" = page_field_definitions.tenant
        and (not (v_filters -> 'entity' is not null and jsonb_typeof(v_filters -> 'entity') <> 'null' and not (jsonb_typeof(v_filters -> 'entity') = 'array' and jsonb_array_length(v_filters -> 'entity') = 0)) or (d."entity")::text = any((case when jsonb_typeof(v_filters -> 'entity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'entity')) else array[v_filters ->> 'entity'] end)::text[]))
        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or d."type"::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{sensitive,0}', v_filters ->> 'sensitive'), '') = 'true', false) or d."sensitive")
        and (coalesce(nullif(coalesce(v_filters #>> '{archived,0}', v_filters ->> 'archived'), '') = 'true', false) or d."archived_at" is null)
        and (v_search is null or d."key" ilike v_search or d."label" ilike v_search)
        and (v_after is null or (d."entity" <= (v_after ->> 0)::text and ((d."entity" < (v_after ->> 0)::text) or (d."entity" = (v_after ->> 0)::text and d."rank" collate "C" > (v_after ->> 1)::text) or (d."entity" = (v_after ->> 0)::text and d."rank" collate "C" = (v_after ->> 1)::text and d."key" > (v_after ->> 2)::text) or (d."entity" = (v_after ->> 0)::text and d."rank" collate "C" = (v_after ->> 1)::text and d."key" = (v_after ->> 2)::text and d."id" > (v_after ->> 3)::uuid))))
      order by d."entity" desc, d."rank" collate "C" asc, d."key" asc, d."id" asc
      limit v_limit + 1 offset v_offset
    ) d
  ) p;
  end if;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."field_definitions" d
      where d."tenant_id" = page_field_definitions.tenant
        and (not (v_filters -> 'entity' is not null and jsonb_typeof(v_filters -> 'entity') <> 'null' and not (jsonb_typeof(v_filters -> 'entity') = 'array' and jsonb_array_length(v_filters -> 'entity') = 0)) or (d."entity")::text = any((case when jsonb_typeof(v_filters -> 'entity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'entity')) else array[v_filters ->> 'entity'] end)::text[]))
        and (not (v_filters -> 'type' is not null and jsonb_typeof(v_filters -> 'type') <> 'null' and not (jsonb_typeof(v_filters -> 'type') = 'array' and jsonb_array_length(v_filters -> 'type') = 0)) or d."type"::text = any((case when jsonb_typeof(v_filters -> 'type') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'type')) else array[v_filters ->> 'type'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{sensitive,0}', v_filters ->> 'sensitive'), '') = 'true', false) or d."sensitive")
        and (coalesce(nullif(coalesce(v_filters #>> '{archived,0}', v_filters ->> 'archived'), '') = 'true', false) or d."archived_at" is null)
        and (v_search is null or d."key" ilike v_search or d."label" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.page_forecast_snapshots (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(page_forecast_snapshots.filters, '{}'::jsonb);
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_sort text := nullif(v_filters ->> 'sort', '');
  v_dir text := nullif(v_filters ->> 'direction', '');
  v_facet text := nullif(v_filters ->> 'facet', '');
  v_count boolean := coalesce((v_filters ->> 'count')::boolean, false);
  v_result jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', page_forecast_snapshots.tenant, 'forecasts.read'), false)) then
    raise exception 'You need forecasts.read to list forecast snapshots' using errcode = '42501', hint = 'FORECAST_FORBIDDEN';
  end if;
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  if v_facet is not null then
    if v_facet not in ('currency', 'pipelineId') then
      raise exception 'facet is one of currency, pipelineId' using errcode = '22023', hint = 'FORECAST_INVALID';
    end if;
    with s as (
      select (case v_facet when 'currency' then (x."currency")::text when 'pipelineId' then (coalesce(x."pipeline_id"::text, ''))::text end) as v
      from "better_supabase"."forecast_snapshots" x
      where x."tenant_id" = page_forecast_snapshots.tenant
        and (not (v_filters -> 'pipelineId' is not null and jsonb_typeof(v_filters -> 'pipelineId') <> 'null' and not (jsonb_typeof(v_filters -> 'pipelineId') = 'array' and jsonb_array_length(v_filters -> 'pipelineId') = 0)) or x."pipeline_id" = any((case when jsonb_typeof(v_filters -> 'pipelineId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'pipelineId')) else array[v_filters ->> 'pipelineId'] end)::uuid[]))
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (not (v_filters -> 'since' is not null and jsonb_typeof(v_filters -> 'since') <> 'null' and not (jsonb_typeof(v_filters -> 'since') = 'array' and jsonb_array_length(v_filters -> 'since') = 0)) or x."period_start" = any((case when jsonb_typeof(v_filters -> 'since') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'since')) else array[v_filters ->> 'since'] end)::date[]))
        and (not (v_filters -> 'until' is not null and jsonb_typeof(v_filters -> 'until') <> 'null' and not (jsonb_typeof(v_filters -> 'until') = 'array' and jsonb_array_length(v_filters -> 'until') = 0)) or x."period_end" = any((case when jsonb_typeof(v_filters -> 'until') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'until')) else array[v_filters ->> 'until'] end)::date[]))
      limit v_total_cap + 1
    )
    select jsonb_build_object('facet', v_facet, 'values', coalesce(jsonb_agg(jsonb_build_object('value', g.v, 'count', jsonb_build_object('value', g.n, 'exact', g.exact)) order by g.n desc, g.v), '[]'::jsonb))
    into v_result
    from (
      select s.v, count(*) as n, (select count(*) from s) <= v_total_cap as exact
      from s where s.v is not null group by s.v order by n desc, s.v limit 100
    ) g;
    return v_result;
  end if;
  if v_count then
    select count(*) into v_total from (
      select 1 from "better_supabase"."forecast_snapshots" x
      where x."tenant_id" = page_forecast_snapshots.tenant
        and (not (v_filters -> 'pipelineId' is not null and jsonb_typeof(v_filters -> 'pipelineId') <> 'null' and not (jsonb_typeof(v_filters -> 'pipelineId') = 'array' and jsonb_array_length(v_filters -> 'pipelineId') = 0)) or x."pipeline_id" = any((case when jsonb_typeof(v_filters -> 'pipelineId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'pipelineId')) else array[v_filters ->> 'pipelineId'] end)::uuid[]))
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (not (v_filters -> 'since' is not null and jsonb_typeof(v_filters -> 'since') <> 'null' and not (jsonb_typeof(v_filters -> 'since') = 'array' and jsonb_array_length(v_filters -> 'since') = 0)) or x."period_start" = any((case when jsonb_typeof(v_filters -> 'since') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'since')) else array[v_filters ->> 'since'] end)::date[]))
        and (not (v_filters -> 'until' is not null and jsonb_typeof(v_filters -> 'until') <> 'null' and not (jsonb_typeof(v_filters -> 'until') = 'array' and jsonb_array_length(v_filters -> 'until') = 0)) or x."period_end" = any((case when jsonb_typeof(v_filters -> 'until') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'until')) else array[v_filters ->> 'until'] end)::date[]))
      limit v_total_cap + 1
    ) c;
    return jsonb_build_object('value', least(v_total, v_total_cap), 'exact', v_total <= v_total_cap);
  end if;
  if v_sort is not null and v_sort not in ('takenAt', 'since', 'dealCount') then
    raise exception 'sort is one of takenAt, since, dealCount' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  if v_dir is not null and v_dir not in ('asc', 'desc') then
    raise exception 'direction is asc or desc' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  if v_sort is null and coalesce(v_dir, 'desc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'pipelineId', x."pipeline_id", 'since', x."period_start", 'until', x."period_end", 'currency', x."currency", 'target', x."target"::text, 'totals', x."totals", 'dealCount', x."deal_count", 'takenBy', x."taken_by", 'takenAt', x."taken_at") as j, jsonb_build_array((x."taken_at")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."forecast_snapshots" x
      where x."tenant_id" = page_forecast_snapshots.tenant
        and (not (v_filters -> 'pipelineId' is not null and jsonb_typeof(v_filters -> 'pipelineId') <> 'null' and not (jsonb_typeof(v_filters -> 'pipelineId') = 'array' and jsonb_array_length(v_filters -> 'pipelineId') = 0)) or x."pipeline_id" = any((case when jsonb_typeof(v_filters -> 'pipelineId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'pipelineId')) else array[v_filters ->> 'pipelineId'] end)::uuid[]))
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (not (v_filters -> 'since' is not null and jsonb_typeof(v_filters -> 'since') <> 'null' and not (jsonb_typeof(v_filters -> 'since') = 'array' and jsonb_array_length(v_filters -> 'since') = 0)) or x."period_start" = any((case when jsonb_typeof(v_filters -> 'since') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'since')) else array[v_filters ->> 'since'] end)::date[]))
        and (not (v_filters -> 'until' is not null and jsonb_typeof(v_filters -> 'until') <> 'null' and not (jsonb_typeof(v_filters -> 'until') = 'array' and jsonb_array_length(v_filters -> 'until') = 0)) or x."period_end" = any((case when jsonb_typeof(v_filters -> 'until') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'until')) else array[v_filters ->> 'until'] end)::date[]))
        and (v_after is null or (x."taken_at", x."id") > ((v_after ->> 0)::timestamptz, (v_after ->> 1)::uuid))
      order by x."taken_at" asc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort is null and coalesce(v_dir, 'desc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'pipelineId', x."pipeline_id", 'since', x."period_start", 'until', x."period_end", 'currency', x."currency", 'target', x."target"::text, 'totals', x."totals", 'dealCount', x."deal_count", 'takenBy', x."taken_by", 'takenAt', x."taken_at") as j, jsonb_build_array((x."taken_at")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."forecast_snapshots" x
      where x."tenant_id" = page_forecast_snapshots.tenant
        and (not (v_filters -> 'pipelineId' is not null and jsonb_typeof(v_filters -> 'pipelineId') <> 'null' and not (jsonb_typeof(v_filters -> 'pipelineId') = 'array' and jsonb_array_length(v_filters -> 'pipelineId') = 0)) or x."pipeline_id" = any((case when jsonb_typeof(v_filters -> 'pipelineId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'pipelineId')) else array[v_filters ->> 'pipelineId'] end)::uuid[]))
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (not (v_filters -> 'since' is not null and jsonb_typeof(v_filters -> 'since') <> 'null' and not (jsonb_typeof(v_filters -> 'since') = 'array' and jsonb_array_length(v_filters -> 'since') = 0)) or x."period_start" = any((case when jsonb_typeof(v_filters -> 'since') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'since')) else array[v_filters ->> 'since'] end)::date[]))
        and (not (v_filters -> 'until' is not null and jsonb_typeof(v_filters -> 'until') <> 'null' and not (jsonb_typeof(v_filters -> 'until') = 'array' and jsonb_array_length(v_filters -> 'until') = 0)) or x."period_end" = any((case when jsonb_typeof(v_filters -> 'until') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'until')) else array[v_filters ->> 'until'] end)::date[]))
        and (v_after is null or (x."taken_at" <= (v_after ->> 0)::timestamptz and ((x."taken_at" < (v_after ->> 0)::timestamptz) or (x."taken_at" = (v_after ->> 0)::timestamptz and x."id" > (v_after ->> 1)::uuid))))
      order by x."taken_at" desc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort = 'takenAt' and coalesce(v_dir, 'desc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'pipelineId', x."pipeline_id", 'since', x."period_start", 'until', x."period_end", 'currency', x."currency", 'target', x."target"::text, 'totals', x."totals", 'dealCount', x."deal_count", 'takenBy', x."taken_by", 'takenAt', x."taken_at") as j, jsonb_build_array((x."taken_at")::text, (x."id")::text) as k
