  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'title', x."title", 'description', x."description", 'severity', x."severity", 'status', x."status", 'public', x."public", 'commanderId', x."commander_id", 'startedAt', x."started_at", 'resolvedAt', x."resolved_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at", 'impacts', (select coalesce(jsonb_agg(jsonb_build_object('componentId', im."component_id", 'name', ic."name", 'impact', im."impact") order by ic."position", ic."name"), '[]'::jsonb) from "better_supabase"."incident_impacts" im join "better_supabase"."incident_status_components" ic on ic."id" = im."component_id" where im."incident_id" = x."id")) as j, jsonb_build_array((x."severity")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."incidents" x
      where x."tenant_id" = page_incidents.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'severity' is not null and jsonb_typeof(v_filters -> 'severity') <> 'null' and not (jsonb_typeof(v_filters -> 'severity') = 'array' and jsonb_array_length(v_filters -> 'severity') = 0)) or (x."severity")::text = any((case when jsonb_typeof(v_filters -> 'severity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'severity')) else array[v_filters ->> 'severity'] end)::text[]))
        and (not (v_filters -> 'componentId' is not null and jsonb_typeof(v_filters -> 'componentId') <> 'null' and not (jsonb_typeof(v_filters -> 'componentId') = 'array' and jsonb_array_length(v_filters -> 'componentId') = 0)) or exists (select 1 from "better_supabase"."incident_impacts" y where y."incident_id" = x."id" and (not (v_filters -> 'componentId' is not null and jsonb_typeof(v_filters -> 'componentId') <> 'null' and not (jsonb_typeof(v_filters -> 'componentId') = 'array' and jsonb_array_length(v_filters -> 'componentId') = 0)) or y."component_id" = any((case when jsonb_typeof(v_filters -> 'componentId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'componentId')) else array[v_filters ->> 'componentId'] end)::uuid[]))))
        and (v_search is null or x."title" ilike v_search)
        and (v_after is null or (x."severity" >= (v_after ->> 0)::text and ((x."severity" > (v_after ->> 0)::text) or (x."severity" = (v_after ->> 0)::text and x."id" < (v_after ->> 1)::uuid))))
      order by x."severity" asc, x."id" desc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort = 'severity' and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'INCIDENTS_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'title', x."title", 'description', x."description", 'severity', x."severity", 'status', x."status", 'public', x."public", 'commanderId', x."commander_id", 'startedAt', x."started_at", 'resolvedAt', x."resolved_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at", 'impacts', (select coalesce(jsonb_agg(jsonb_build_object('componentId', im."component_id", 'name', ic."name", 'impact', im."impact") order by ic."position", ic."name"), '[]'::jsonb) from "better_supabase"."incident_impacts" im join "better_supabase"."incident_status_components" ic on ic."id" = im."component_id" where im."incident_id" = x."id")) as j, jsonb_build_array((x."severity")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."incidents" x
      where x."tenant_id" = page_incidents.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'severity' is not null and jsonb_typeof(v_filters -> 'severity') <> 'null' and not (jsonb_typeof(v_filters -> 'severity') = 'array' and jsonb_array_length(v_filters -> 'severity') = 0)) or (x."severity")::text = any((case when jsonb_typeof(v_filters -> 'severity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'severity')) else array[v_filters ->> 'severity'] end)::text[]))
        and (not (v_filters -> 'componentId' is not null and jsonb_typeof(v_filters -> 'componentId') <> 'null' and not (jsonb_typeof(v_filters -> 'componentId') = 'array' and jsonb_array_length(v_filters -> 'componentId') = 0)) or exists (select 1 from "better_supabase"."incident_impacts" y where y."incident_id" = x."id" and (not (v_filters -> 'componentId' is not null and jsonb_typeof(v_filters -> 'componentId') <> 'null' and not (jsonb_typeof(v_filters -> 'componentId') = 'array' and jsonb_array_length(v_filters -> 'componentId') = 0)) or y."component_id" = any((case when jsonb_typeof(v_filters -> 'componentId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'componentId')) else array[v_filters ->> 'componentId'] end)::uuid[]))))
        and (v_search is null or x."title" ilike v_search)
        and (v_after is null or (x."severity", x."id") < ((v_after ->> 0)::text, (v_after ->> 1)::uuid))
      order by x."severity" desc, x."id" desc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  end if;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."incidents" x
      where x."tenant_id" = page_incidents.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (x."status")::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'severity' is not null and jsonb_typeof(v_filters -> 'severity') <> 'null' and not (jsonb_typeof(v_filters -> 'severity') = 'array' and jsonb_array_length(v_filters -> 'severity') = 0)) or (x."severity")::text = any((case when jsonb_typeof(v_filters -> 'severity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'severity')) else array[v_filters ->> 'severity'] end)::text[]))
        and (not (v_filters -> 'componentId' is not null and jsonb_typeof(v_filters -> 'componentId') <> 'null' and not (jsonb_typeof(v_filters -> 'componentId') = 'array' and jsonb_array_length(v_filters -> 'componentId') = 0)) or exists (select 1 from "better_supabase"."incident_impacts" y where y."incident_id" = x."id" and (not (v_filters -> 'componentId' is not null and jsonb_typeof(v_filters -> 'componentId') <> 'null' and not (jsonb_typeof(v_filters -> 'componentId') = 'array' and jsonb_array_length(v_filters -> 'componentId') = 0)) or y."component_id" = any((case when jsonb_typeof(v_filters -> 'componentId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'componentId')) else array[v_filters ->> 'componentId'] end)::uuid[]))))
        and (v_search is null or x."title" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.page_inventory_levels (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(page_inventory_levels.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_sort text := nullif(v_filters ->> 'sort', '');
  v_dir text := nullif(v_filters ->> 'direction', '');
  v_facet text := nullif(v_filters ->> 'facet', '');
  v_count boolean := coalesce((v_filters ->> 'count')::boolean, false);
  v_result jsonb;
begin
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'INVENTORY_INVALID';
  end if;
  if v_facet is not null then
    if v_facet not in ('status', 'locationId') then
      raise exception 'facet is one of status, locationId' using errcode = '22023', hint = 'INVENTORY_INVALID';
    end if;
    with s as (
      select (case v_facet when 'status' then (case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end)::text when 'locationId' then (x."location_id"::text)::text end) as v
      from "better_supabase"."stock_levels" x
      where x."tenant_id" = page_inventory_levels.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end)::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'variantId' is not null and jsonb_typeof(v_filters -> 'variantId') <> 'null' and not (jsonb_typeof(v_filters -> 'variantId') = 'array' and jsonb_array_length(v_filters -> 'variantId') = 0)) or x."variant_id" = any((case when jsonb_typeof(v_filters -> 'variantId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'variantId')) else array[v_filters ->> 'variantId'] end)::uuid[]))
        and (not (v_filters -> 'locationId' is not null and jsonb_typeof(v_filters -> 'locationId') <> 'null' and not (jsonb_typeof(v_filters -> 'locationId') = 'array' and jsonb_array_length(v_filters -> 'locationId') = 0)) or x."location_id" = any((case when jsonb_typeof(v_filters -> 'locationId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'locationId')) else array[v_filters ->> 'locationId'] end)::uuid[]))
        and (v_search is null or x."variant_id"::text ilike v_search or x."location_id"::text ilike v_search)
      limit v_total_cap + 1
    )
    select jsonb_build_object('facet', v_facet, 'values', coalesce(jsonb_agg(jsonb_build_object('value', g.v, 'count', jsonb_build_object('value', g.n, 'exact', g.exact)) order by g.n desc, g.v), '[]'::jsonb))
    into v_result
    from (
      select s.v, count(*) as n, (select count(*) from s) <= v_total_cap as exact
      from s where s.v is not null group by s.v order by n desc, s.v limit 100
    ) g;
    return v_result;
  end if;
  if v_count then
    select count(*) into v_total from (
      select 1 from "better_supabase"."stock_levels" x
      where x."tenant_id" = page_inventory_levels.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end)::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'variantId' is not null and jsonb_typeof(v_filters -> 'variantId') <> 'null' and not (jsonb_typeof(v_filters -> 'variantId') = 'array' and jsonb_array_length(v_filters -> 'variantId') = 0)) or x."variant_id" = any((case when jsonb_typeof(v_filters -> 'variantId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'variantId')) else array[v_filters ->> 'variantId'] end)::uuid[]))
        and (not (v_filters -> 'locationId' is not null and jsonb_typeof(v_filters -> 'locationId') <> 'null' and not (jsonb_typeof(v_filters -> 'locationId') = 'array' and jsonb_array_length(v_filters -> 'locationId') = 0)) or x."location_id" = any((case when jsonb_typeof(v_filters -> 'locationId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'locationId')) else array[v_filters ->> 'locationId'] end)::uuid[]))
        and (v_search is null or x."variant_id"::text ilike v_search or x."location_id"::text ilike v_search)
      limit v_total_cap + 1
    ) c;
    return jsonb_build_object('value', least(v_total, v_total_cap), 'exact', v_total <= v_total_cap);
  end if;
  if v_sort is not null and v_sort not in ('available', 'onHand', 'variantId') then
    raise exception 'sort is one of available, onHand, variantId' using errcode = '22023', hint = 'INVENTORY_INVALID';
  end if;
  if v_dir is not null and v_dir not in ('asc', 'desc') then
    raise exception 'direction is asc or desc' using errcode = '22023', hint = 'INVENTORY_INVALID';
  end if;
  if v_sort is null and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'INVENTORY_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object(
      'id', x."variant_id"::text || ':' || x."location_id"::text,
      'variantId', x."variant_id",
      'locationId', x."location_id",
      'onHand', x."on_hand"::text,
      'allocated', x."reserved"::text,
      'available', x."available"::text,
      'incoming', x."incoming"::text,
      'reorderPoint', x."reorder_point"::text,
      'status', case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end) as j, jsonb_build_array((x."available")::text, ((x."variant_id"::text || ':' || x."location_id"::text))::text) as k
    from (
      select * from "better_supabase"."stock_levels" x
      where x."tenant_id" = page_inventory_levels.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end)::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'variantId' is not null and jsonb_typeof(v_filters -> 'variantId') <> 'null' and not (jsonb_typeof(v_filters -> 'variantId') = 'array' and jsonb_array_length(v_filters -> 'variantId') = 0)) or x."variant_id" = any((case when jsonb_typeof(v_filters -> 'variantId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'variantId')) else array[v_filters ->> 'variantId'] end)::uuid[]))
        and (not (v_filters -> 'locationId' is not null and jsonb_typeof(v_filters -> 'locationId') <> 'null' and not (jsonb_typeof(v_filters -> 'locationId') = 'array' and jsonb_array_length(v_filters -> 'locationId') = 0)) or x."location_id" = any((case when jsonb_typeof(v_filters -> 'locationId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'locationId')) else array[v_filters ->> 'locationId'] end)::uuid[]))
        and (v_search is null or x."variant_id"::text ilike v_search or x."location_id"::text ilike v_search)
        and (v_after is null or (x."available", (x."variant_id"::text || ':' || x."location_id"::text)) > ((v_after ->> 0)::numeric, (v_after ->> 1)::text))
      order by x."available" asc, (x."variant_id"::text || ':' || x."location_id"::text) asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort is null and coalesce(v_dir, 'asc') = 'desc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'INVENTORY_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object(
      'id', x."variant_id"::text || ':' || x."location_id"::text,
      'variantId', x."variant_id",
      'locationId', x."location_id",
      'onHand', x."on_hand"::text,
      'allocated', x."reserved"::text,
      'available', x."available"::text,
      'incoming', x."incoming"::text,
      'reorderPoint', x."reorder_point"::text,
      'status', case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end) as j, jsonb_build_array((x."available")::text, ((x."variant_id"::text || ':' || x."location_id"::text))::text) as k
    from (
      select * from "better_supabase"."stock_levels" x
      where x."tenant_id" = page_inventory_levels.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or (case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end)::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'variantId' is not null and jsonb_typeof(v_filters -> 'variantId') <> 'null' and not (jsonb_typeof(v_filters -> 'variantId') = 'array' and jsonb_array_length(v_filters -> 'variantId') = 0)) or x."variant_id" = any((case when jsonb_typeof(v_filters -> 'variantId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'variantId')) else array[v_filters ->> 'variantId'] end)::uuid[]))
        and (not (v_filters -> 'locationId' is not null and jsonb_typeof(v_filters -> 'locationId') <> 'null' and not (jsonb_typeof(v_filters -> 'locationId') = 'array' and jsonb_array_length(v_filters -> 'locationId') = 0)) or x."location_id" = any((case when jsonb_typeof(v_filters -> 'locationId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'locationId')) else array[v_filters ->> 'locationId'] end)::uuid[]))
        and (v_search is null or x."variant_id"::text ilike v_search or x."location_id"::text ilike v_search)
        and (v_after is null or (x."available" <= (v_after ->> 0)::numeric and ((x."available" < (v_after ->> 0)::numeric) or (x."available" = (v_after ->> 0)::numeric and (x."variant_id"::text || ':' || x."location_id"::text) > (v_after ->> 1)::text))))
      order by x."available" desc, (x."variant_id"::text || ':' || x."location_id"::text) asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  elsif v_sort = 'available' and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'INVENTORY_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object(
      'id', x."variant_id"::text || ':' || x."location_id"::text,
      'variantId', x."variant_id",
      'locationId', x."location_id",
      'onHand', x."on_hand"::text,
      'allocated', x."reserved"::text,
      'available', x."available"::text,
      'incoming', x."incoming"::text,
      'reorderPoint', x."reorder_point"::text,
      'status', case when x."available" <= 0 then 'out' when x."reorder_point" is not null and x."available" <= x."reorder_point" then 'low' else 'in_stock' end) as j, jsonb_build_array((x."available")::text, ((x."variant_id"::text || ':' || x."location_id"::text))::text) as k
    from (
      select * from "better_supabase"."stock_levels" x
