        and (v_after is null or (x."enrolled_at" >= (v_after ->> 0)::timestamptz and ((x."enrolled_at" > (v_after ->> 0)::timestamptz) or (x."enrolled_at" = (v_after ->> 0)::timestamptz and x."id" < (v_after ->> 1)::uuid))))
      order by x."enrolled_at" asc, x."id" desc
