  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'code', x."code", 'name', x."name", 'kind', x."kind", 'active', x."active") as j, jsonb_build_array((x."code")::text, (x."id")::text) as k
    from (
