    select row_number() over () as n, jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'vulnId', y."vuln_id", 'aliases', to_jsonb(y."aliases"), 'summary', y."summary", 'details', y."details", 'cvssVector', y."cvss_vector", 'cvssVersion', y."cvss_version", 'cvssScore', y."cvss_score", 'severity', y."severity", 'epssScore', y."epss_score", 'epssPercentile', y."epss_percentile", 'epssDate', y."epss_date", 'kev', y."kev", 'kevAddedOn', y."kev_added_on", 'kevDueOn', y."kev_due_on", 'kevRansomware', y."kev_ransomware", 'affectedPurls', to_jsonb(y."affected_purls"), 'references', y."reference_links", 'publishedAt', y."published_at", 'modifiedAt', y."modified_at", 'enrichedAt', y."enriched_at", 'createdAt', y."created_at", 'updatedAt', y."updated_at") as j, jsonb_build_array((coalesce(y."epss_score", -1))::text, (y."id")::text) as k
    from (
      select * from "better_supabase"."vulnerabilities" y
      where y."tenant_id" = page_vulnerabilities.tenant
        and (not (v_filters -> 'severity' is not null and jsonb_typeof(v_filters -> 'severity') <> 'null' and not (jsonb_typeof(v_filters -> 'severity') = 'array' and jsonb_array_length(v_filters -> 'severity') = 0)) or (coalesce(y."severity"::text, 'none'))::text = any((case when jsonb_typeof(v_filters -> 'severity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'severity')) else array[v_filters ->> 'severity'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{kev,0}', v_filters ->> 'kev'), '') = 'true', false) or y."kev")
        and (v_search is null or y."vuln_id" ilike v_search or y."summary" ilike v_search)
        and (v_after is null or (coalesce(y."epss_score", -1) <= (v_after ->> 0)::numeric and ((coalesce(y."epss_score", -1) < (v_after ->> 0)::numeric) or (coalesce(y."epss_score", -1) = (v_after ->> 0)::numeric and y."id" > (v_after ->> 1)::uuid))))
      order by coalesce(y."epss_score", -1) desc, y."id" asc
      limit v_limit + 1 offset v_offset
    ) y
  ) p;
  end if;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."vulnerabilities" y
      where y."tenant_id" = page_vulnerabilities.tenant
        and (not (v_filters -> 'severity' is not null and jsonb_typeof(v_filters -> 'severity') <> 'null' and not (jsonb_typeof(v_filters -> 'severity') = 'array' and jsonb_array_length(v_filters -> 'severity') = 0)) or (coalesce(y."severity"::text, 'none'))::text = any((case when jsonb_typeof(v_filters -> 'severity') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'severity')) else array[v_filters ->> 'severity'] end)::text[]))
        and (not coalesce(nullif(coalesce(v_filters #>> '{kev,0}', v_filters ->> 'kev'), '') = 'true', false) or y."kev")
        and (v_search is null or y."vuln_id" ilike v_search or y."summary" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.page_work_centers (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(page_work_centers.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_sort text := nullif(v_filters ->> 'sort', '');
  v_dir text := nullif(v_filters ->> 'direction', '');
  v_facet text := nullif(v_filters ->> 'facet', '');
  v_count boolean := coalesce((v_filters ->> 'count')::boolean, false);
  v_result jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (page_work_centers.tenant is not null and coalesce(better_supabase.can('tenant', page_work_centers.tenant, 'manufacturing.read'), false))) then
    raise exception 'not allowed to read work centers' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
  end if;
  if v_facet is not null then
    if v_facet not in ('currency') then
      raise exception 'facet is one of currency' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
    end if;
    with s as (
      select (case v_facet when 'currency' then (x."currency")::text end) as v
      from "better_supabase"."work_centers" x
      where x."tenant_id" = page_work_centers.tenant
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (coalesce(nullif(coalesce(v_filters #>> '{includeArchived,0}', v_filters ->> 'includeArchived'), '') = 'true', false) or x."archived_at" is null)
        and (v_search is null or x."name" ilike v_search)
      limit v_total_cap + 1
    )
    select jsonb_build_object('facet', v_facet, 'values', coalesce(jsonb_agg(jsonb_build_object('value', g.v, 'count', jsonb_build_object('value', g.n, 'exact', g.exact)) order by g.n desc, g.v), '[]'::jsonb))
    into v_result
    from (
      select s.v, count(*) as n, (select count(*) from s) <= v_total_cap as exact
      from s where s.v is not null group by s.v order by n desc, s.v limit 100
    ) g;
    return v_result;
  end if;
  if v_count then
    select count(*) into v_total from (
      select 1 from "better_supabase"."work_centers" x
      where x."tenant_id" = page_work_centers.tenant
        and (not (v_filters -> 'currency' is not null and jsonb_typeof(v_filters -> 'currency') <> 'null' and not (jsonb_typeof(v_filters -> 'currency') = 'array' and jsonb_array_length(v_filters -> 'currency') = 0)) or (x."currency")::text = any((case when jsonb_typeof(v_filters -> 'currency') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'currency')) else array[v_filters ->> 'currency'] end)::text[]))
        and (coalesce(nullif(coalesce(v_filters #>> '{includeArchived,0}', v_filters ->> 'includeArchived'), '') = 'true', false) or x."archived_at" is null)
        and (v_search is null or x."name" ilike v_search)
      limit v_total_cap + 1
    ) c;
    return jsonb_build_object('value', least(v_total, v_total_cap), 'exact', v_total <= v_total_cap);
  end if;
  if v_sort is not null and v_sort not in ('name', 'createdAt') then
    raise exception 'sort is one of name, createdAt' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
  end if;
  if v_dir is not null and v_dir not in ('asc', 'desc') then
    raise exception 'direction is asc or desc' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
  end if;
  if v_sort is null and coalesce(v_dir, 'asc') = 'asc' then
    if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
  end if;
